effect.shader:
vec3 bright(vec3 c) {
    float L = dot(c, vec3(0.2126, 0.7152, 0.0722));
    return c * max(0.0, L - threshold);
}

void main() {
    vec2 uv = acScreenNorm;
    vec4 base = texture(inputImg, uv);

    vec3 glow = vec3(0.0);
    float wsum = 0.0;
    float r = radius;
    for (int i = 0; i < 16; i++) {
        float ang = float(i) * 0.3927; // 22.5°
        for (int j = 1; j <= 3; j++) {
            float rr = r * float(j) / 3.0;
            vec2 off = vec2(cos(ang), sin(ang)) * rr / acResolution;
            float w = exp(-float(j) * float(j) * 0.4);
            glow += bright(texture(inputImg, uv + off).rgb) * w;
            wsum += w;
        }
    }
    glow = glow * intensity / wsum;

    vec3 outRgb = base.rgb + glow * mistura;
    fragColor = vec4(outRgb, base.a);
}
